using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class CMUpdate {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 static Material ColorMaterial(string name,Color color,float metallic,float smooth){string path="Assets/Afrer_Seconds/05.Model/Props/B2/Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.name=name;m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",smooth);EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);return m;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");string asset="Assets/Afrer_Seconds/05.Model/Props/B2/VA_BM_CoolingPump.fbx";AssetDatabase.ImportAsset(asset,ImportAssetOptions.ForceSynchronousImport);var importer=(ModelImporter)AssetImporter.GetAtPath(asset);importer.isReadable=false;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.importNormals=ModelImporterNormals.Import;importer.importTangents=ModelImporterTangents.CalculateMikk;importer.SaveAndReimport();var meshes=AssetDatabase.LoadAllAssetsAtPath(asset).OfType<Mesh>().OrderBy(x=>x.name).ToArray();if(meshes.Length!=2||meshes.Any(m=>m.subMeshCount!=4))throw new Exception("Expected two LODs, four material slots");
 var original=AssetDatabase.LoadAssetAtPath<Material>("Assets/Afrer_Seconds/05.Model/Props/B5/Materials/Props_CoolingPump_URP.mat");var metal=AssetDatabase.LoadAssetAtPath<Material>("Assets/Afrer_Seconds/05.Model/Props/B2/Materials/VA_CoolingPump_AlignedMetal.mat");var orange=ColorMaterial("VA_CoolingPump_Orange",new Color(.72f,.265f,.035f,1),.08f,.34f);var dark=ColorMaterial("VA_CoolingPump_Dark",new Color(.025f,.030f,.035f,1),.05f,.24f);var mats=new[]{original,metal,orange,dark};var sourceNames=new[]{"CP_Original_PBR","CP_Aligned_Metal","CP_Orange_Paint","CP_Dark_Inside"};for(int i=0;i<4;i++)importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),sourceNames[i]),mats[i]);importer.SaveAndReimport();meshes=AssetDatabase.LoadAllAssetsAtPath(asset).OfType<Mesh>().OrderBy(x=>x.name).ToArray();var model=AssetDatabase.LoadAssetAtPath<GameObject>(asset);var assignments=model.GetComponentsInChildren<MeshFilter>(true).ToDictionary(mf=>mf.sharedMesh.name,mf=>mf.GetComponent<Renderer>().sharedMaterials);foreach(var arr in assignments.Values)if(arr.Length!=4||arr.Any(m=>!mats.Contains(m)))throw new Exception("Material remap failed: "+string.Join(",",arr.Select(m=>m?m.name:"missing")));var data=JObject.Parse(File.ReadAllText(R+"/SourceAssets/CoolingPumpMotorRepair/before.json"));var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var changed=new List<string>();
 foreach(var row in data["rows"].Where(x=>(string)x["model"]=="BM_CoolingPump")){var root=ts.Single(x=>x.name==(string)row["name"]);var rr=root.GetComponentsInChildren<MeshRenderer>().Where(x=>x.name.StartsWith("Aligned_LOD")).OrderBy(x=>x.name).ToArray();if(rr.Length!=2)throw new Exception("Missing aligned LODs: "+root.name);for(int i=0;i<2;i++){rr[i].GetComponent<MeshFilter>().sharedMesh=meshes[i];rr[i].sharedMaterials=assignments[meshes[i].name];EditorUtility.SetDirty(rr[i]);}changed.Add(root.name);}
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText(R+"/SourceAssets/CoolingPumpMotorRepair/applied.json",JsonConvert.SerializeObject(new{scene=s.path,asset,placements=changed,triangles=meshes.Select(m=>m.triangles.Length/3)},Formatting.Indented));return new{saved=true,placements=changed.Count,meshTriangles=meshes.Select(m=>m.triangles.Length/3)};}
}
